// Enhanced Express.js application with security best practices
// and comprehensive error handling

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult, param } = require('express-validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers with Helmet
app.use(helmet());

// 2. Enable CORS with secure configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST'],
  credentials: false // Set to true if you need cookies/auth headers
}));

// 3. Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Request body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Logging middleware
app.use(morgan('combined'));

// ========== CUSTOM MIDDLEWARE ==========

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array()
    });
  }
  next();
};

// Global error handler middleware
const errorHandler = (err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const errorResponse = {
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message
  };

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      ...errorResponse,
      message: 'Validation error',
      errors: err.errors
    });
  }

  if (err.name === 'NotFoundError') {
    return res.status(404).json({
      ...errorResponse,
      message: 'Resource not found'
    });
  }

  // Default 500 error
  res.status(500).json(errorResponse);
};

// 404 handler
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    success: false,
    message: `Route ${req.method} ${req.originalUrl} not found`,
    timestamp: new Date().toISOString()
  });
};

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memoryUsage: process.memoryUsage()
  });
});

// Users endpoint with validation
app.get('/users', 
  [
    // Query parameter validation
    param('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    param('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer')
  ],
  validateInput,
  (req, res) => {
    try {
      const { limit = 10, page = 1 } = req.query;

      // Simulate database query with error possibility
      if (Math.random() < 0.05) {
        throw new Error('Database connection failed');
      }

      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          createdAt: new Date().toISOString()
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          createdAt: new Date().toISOString()
        },
      ];

      res.json({
        success: true,
        data: users,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: users.length,
          pages: Math.ceil(users.length / limit)
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      // Log and rethrow for global error handler
      console.error('Error fetching users:', error);
      throw error;
    }
  }
);

// New user creation endpoint with comprehensive validation
app.post('/users',
  [
    // Input validation using express-validator
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Please provide a valid email address')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),

    body('password')
      .optional()
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      .matches(/[A-Z]/).withMessage('Password must contain at least one uppercase letter')
      .matches(/[a-z]/).withMessage('Password must contain at least one lowercase letter')
      .matches(/[0-9]/).withMessage('Password must contain at least one number')
  ],
  validateInput,
  (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Sanitize input further if needed
      const sanitizedName = name.replace(/[<>]/g, ''); // Basic HTML tag removal

      // Simulate user creation
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 3,
        name: sanitizedName,
        email,
        age: age || null,
        createdAt: new Date().toISOString()
      };

      // In real app, you would save to database here
      // await User.create(newUser);

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Error creating user:', error);
      throw error;
    }
  }
);

// User by ID endpoint with parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ],
  validateInput,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Simulate database lookup
      const user = userId === 1 
        ? { id: 1, name: 'Alice', email: 'alice@example.com' }
        : null;

      if (!user) {
        const notFoundError = new Error(`User with ID ${userId} not found`);
        notFoundError.name = 'NotFoundError';
        throw notFoundError;
      }

      res.json({
        success: true,
        data: user,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error(`Error fetching user ${req.params.id}:`, error);
      throw error;
    }
  }
);

// ========== ERROR HANDLING MIDDLEWARE ==========

// Apply 404 handler for undefined routes
app.use(notFoundHandler);

// Apply global error handler (must be last)
app.use(errorHandler);

// ========== SERVER SETUP ==========

// Get port from environment variable or use default
const PORT = process.env.PORT || 3000;

// Handle uncaught exceptions and rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Perform cleanup if needed
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Perform cleanup if needed
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Health check: http://localhost:${PORT}/health`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server...');

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = { app, server };

