// Improved Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize express app
const app = express();

// Security middleware setup
app.use(helmet()); // Set security HTTP headers
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting - protect against brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Request logging middleware
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ],
});

// Custom request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString()
    });
  });
  next();
});

// Enhanced health endpoint with validation
app.get('/health', [
  // Input validation for query parameters
  body('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
], (req, res, next) => {
  try {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        errors: errors.array(),
        timestamp: new Date().toISOString()
      });
    }

    // Check system health (example checks)
    const healthChecks = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version
    };

    if (req.query.detailed === 'true') {
      healthChecks.detailed = {
        platform: process.platform,
        architecture: process.arch,
        cpuCount: require('os').cpus().length,
        freeMemory: require('os').freemem(),
        totalMemory: require('os').totalmem()
      };
    }

    res.json(healthChecks);
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Enhanced users endpoint with validation and sanitization
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  body('search').optional().isString().trim().escape().withMessage('Search must be a string'),
], async (req, res, next) => {
  try {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        errors: errors.array(),
        timestamp: new Date().toISOString()
      });
    }

    // Example user data (in reality, this would come from a database)
    const mockUsers = [
      { 
        id: 1, 
        name: 'Alice Smith', 
        email: 'alice@example.com',
        role: 'user',
        createdAt: '2024-01-01T00:00:00Z'
      },
      { 
        id: 2, 
        name: 'Bob Johnson', 
        email: 'bob@example.com',
        role: 'admin',
        createdAt: '2024-01-02T00:00:00Z'
      },
      { 
        id: 3, 
        name: 'Charlie Brown', 
        email: 'charlie@example.com',
        role: 'user',
        createdAt: '2024-01-03T00:00:00Z'
      }
    ];

    // Apply filters based on query parameters
    let filteredUsers = [...mockUsers];

    // Search filter (case-insensitive)
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Sanitize output - remove sensitive information if user is not admin
    const sanitizedUsers = paginatedUsers.map(user => {
      // In a real app, you would check user permissions here
      const sanitizedUser = { ...user };
      if (req.headers['x-user-role'] !== 'admin') {
        delete sanitizedUser.role;
        delete sanitizedUser.createdAt;
      }
      return sanitizedUser;
    });

    res.json({
      status: 'success',
      data: sanitizedUsers,
      meta: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Log the error
  logger.error({
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine error type and respond appropriately
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(statusCode).json({
    status: 'error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  const port = server.address().port;
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${port}`);

  // Log startup information
  logger.info({
    message: 'Server started',
    port,
    nodeVersion: process.version,
    environment: process.env.NODE_ENV || 'development',
    pid: process.pid,
    timestamp: new Date().toISOString()
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection at:',
    promise,
    reason,
    timestamp: new Date().toISOString()
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error({
    message: 'Uncaught Exception:',
    error: error.message,
    stack: error.stack,
    timestamp: new Date().toISOString()
  });
  // In production, you might want to restart the process here
  process.exit(1);
});

// Graceful shutdown
const shutdownSignals = ['SIGTERM', 'SIGINT'];
shutdownSignals.forEach(signal => {
  process.on(signal, () => {
    logger.info({
      message: `${signal} received, starting graceful shutdown`,
      timestamp: new Date().toISOString()
    });

    server.close(() => {
      logger.info({
        message: 'Server closed',
        timestamp: new Date().toISOString()
      });
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      logger.error({
        message: 'Could not close connections in time, forcing shutdown',
        timestamp: new Date().toISOString()
      });
      process.exit(1);
    }, 10000);
  });
});

module.exports = app;

// Test file to demonstrate security improvements
const app = require('./app_improved.js');

// Example of potential security issues and how they're handled

console.log('=== Security Test Cases ===\n');

// Test 1: Try XSS attack attempt
console.log('Test 1: XSS Attempt Protection');
const xssPayload = '<script>alert("XSS")</script>';
console.log(`Sanitized XSS payload: ${xssPayload}`);
console.log('Expected: XSS middleware should sanitize this input');
console.log('---\n');

// Test 2: Try NoSQL injection attempt
console.log('Test 2: NoSQL Injection Protection');
const nosqlPayload = { '$where': '1 == 1' };
console.log(`NoSQL injection payload: ${JSON.stringify(nosqlPayload)}`);
console.log('Expected: Mongo sanitize middleware should remove $ operators');
console.log('---\n');

// Test 3: Try parameter pollution
console.log('Test 3: Parameter Pollution Protection');
const pollutionPayload = 'color=red&color=blue&color=green';
console.log(`Parameter pollution: ${pollutionPayload}`);
console.log('Expected: hpp middleware should only accept last value');
console.log('---\n');

// Test 4: Test validation errors
console.log('Test 4: Input Validation');
const invalidInputs = [
  { name: 'limit', value: 'not-a-number', expected: 'validation error' },
  { name: 'limit', value: '0', expected: 'min 1 validation error' },
  { name: 'limit', value: '200', expected: 'max 100 validation error' },
  { name: 'search', value: '<script>alert(1)</script>', expected: 'sanitized and escaped' }
];

invalidInputs.forEach(input => {
  console.log(`Invalid ${input.name}: ${input.value} -> Expected: ${input.expected}`);
});
console.log('---\n');

// Test 5: Test rate limiting
console.log('Test 5: Rate Limiting');
console.log('Rate limiter configured: 100 requests per 15 minutes per IP');
console.log('Expected: Additional requests return 429 status code');
console.log('---\n');

// Test 6: Test security headers
console.log('Test 6: Security Headers (Helmet.js)');
const expectedHeaders = [
  'Content-Security-Policy',
  'X-Frame-Options',
  'X-Content-Type-Options',
  'Strict-Transport-Security',
  'X-Download-Options',
  'X-Permitted-Cross-Domain-Policies',
  'Referrer-Policy'
];
console.log('Expected security headers:');
expectedHeaders.forEach(header => {
  console.log(`  - ${header}`);
});
console.log('---\n');

// Test 7: Test error handling
console.log('Test 7: Structured Error Responses');
console.log('All errors return consistent format:');
console.log('{');
console.log('  "status": "error",');
console.log('  "message": "Error description",');
console.log('  "timestamp": "ISO timestamp",');
console.log('  ...additional data');
console.log('}');
console.log('---\n');

// Test 8: Test logging
console.log('Test 8: Request Logging');
console.log('All requests logged with:');
console.log('  - Method, URL, status code');
console.log('  - Duration in milliseconds');
console.log('  - Client IP address');
console.log('  - User agent');
console.log('  - Timestamp');
console.log('Errors logged to separate error.log file');
console.log('---\n');

console.log('=== Security Best Practices Summary ===');
console.log('✅ Input validation and sanitization');
console.log('✅ XSS protection');
console.log('✅ NoSQL injection prevention');
console.log('✅ Parameter pollution prevention');
console.log('✅ Rate limiting');
console.log('✅ Security headers');
console.log('✅ Structured error handling');
console.log('✅ Comprehensive logging');
console.log('✅ Environment-based configuration');
console.log('✅ Graceful shutdown handling');
console.log('✅ Unhandled error catching');

console.log('\nNote: In a real application, you should also:');
console.log('1. Implement proper authentication (JWT, OAuth, etc.)');
console.log('2. Add database security layer');
console.log('3. Implement API key validation');
console.log('4. Add request/response encryption');
console.log('5. Set up monitoring and alerting');
console.log('6. Regular security audits and penetration testing');

# Summary of Security Improvements for app.js

## Current App.js Issues:
1. **No input validation** - Accepts any input without checking
2. **No error handling** - No global error handling middleware
3. **No security headers** - Missing security HTTP headers
4. **No rate limiting** - Vulnerable to brute force attacks
5. **Hardcoded configuration** - Port hardcoded, no environment variables
6. **No logging** - No request/error logging
7. **No input sanitization** - Vulnerable to XSS and injection attacks
8. **No size limits** - No request size limits
9. **No graceful shutdown** - Doesn't handle process signals properly
10. **No unhandled error catching** - Missing unhandled promise rejection handling

## Major Improvements in app_improved.js:

### 1. **Security Middleware** (Lines 16-45)
```javascript
app.use(helmet()); // Security headers
app.use(cors()); // CORS configuration
app.use(limiter); // Rate limiting (100 requests/15min per IP)
app.use(xss()); // XSS protection
app.use(mongoSanitize()); // NoSQL injection prevention
app.use(hpp()); // Parameter pollution prevention
```

### 2. **Input Validation** (Lines 72-85, 112-119)
```javascript
// Using express-validator
body('limit').optional().isInt({ min: 1, max: 100 })
body('search').optional().isString().trim().escape()
const errors = validationResult(req);
if (!errors.isEmpty()) {
  return res.status(400).json({ errors: errors.array() });
}
```

### 3. **Error Handling Middleware** (Lines 174-197)
```javascript
app.use((err, req, res, next) => {
  // Log error with Winston
  logger.error({ error: err.message, stack: err.stack });

  // Return structured error response
  res.status(err.statusCode || 500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' ? 'An error occurred' : err.message,
    timestamp: new Date().toISOString()
  });
});
```

### 4. **Request Logging** (Lines 49-67)
