// Enhanced Express.js application with comprehensive error handling and security
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // XSS protection
const hpp = require('hpp'); // HTTP parameter pollution protection
const cors = require('cors'); // CORS configuration
const compression = require('compression'); // Response compression
const mongoSanitize = require('express-mongo-sanitize'); // NoSQL injection protection

const app = express();

// Load environment variables safely
require('dotenv').config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

// ========== SECURITY MIDDLEWARE ==========

// Set security HTTP headers
app.use(helmet());

// Enable CORS with safe defaults
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Limit request size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against XSS
app.use(xss());

// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent HTTP parameter pollution
app.use(hpp());

// Enable response compression
app.use(compression());

// ========== RATE LIMITING ==========

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use('/api', limiter);

// ========== INPUT VALIDATION MIDDLEWARE ==========

// Custom middleware for input validation
const validateRequest = (req, res, next) => {
  // Check if request has unexpected content-type
  if (req.is('json') && !req.body) {
    return res.status(400).json({ 
      error: 'Invalid JSON payload' 
    });
  }
  next();
};

app.use(validateRequest);

// ========== ROUTES WITH IMPROVED VALIDATION ==========

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page = 1, limit = 10, sort = 'id' } = req.query;

    // Input validation
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    if (isNaN(pageNum) || pageNum < 1) {
      throw new Error('Invalid page parameter');
    }

    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      throw new Error('Invalid limit parameter (must be between 1 and 100)');
    }

    // Validate sort parameter (whitelist approach)
    const allowedSortFields = ['id', 'name', 'email'];
    if (!allowedSortFields.includes(sort)) {
      throw new Error(`Invalid sort field. Allowed: ${allowedSortFields.join(', ')}`);
    }

    // Simulated database response with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output (prevent accidental data leakage)
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Email is included but could be hashed or partially masked in production
      email: process.env.NODE_ENV === 'production' 
        ? user.email.replace(/(?<=.).(?=.*@)/g, '*')
        : user.email
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: sanitizedUsers.length,
        totalPages: Math.ceil(sanitizedUsers.length / limitNum)
      }
    });

  } catch (error) {
    // Log error for debugging (in production, use a proper logger)
    console.error('Error in /users endpoint:', error.message);

    res.status(400).json({
      success: false,
      error: error.message,
      code: 'VALIDATION_ERROR'
    });
  }
});

// ========== ERROR HANDLING MIDDLEWARE ==========

// Catch 404 and forward to error handler
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error (in production, use Winston, Pino, or similar)
  console.error('Application error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Determine error message (hide sensitive details in production)
  const errorMessage = process.env.NODE_ENV === 'production' 
    ? statusCode === 500 ? 'Internal server error' : err.message
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: errorMessage,
    code: err.code || 'INTERNAL_ERROR',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

  // Verify critical environment variables
  const requiredEnvVars = ['NODE_ENV'];
  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.warn(`Warning: Missing environment variables: ${missingVars.join(', ')}`);
  }

  // Log startup with security information
  console.log(`Security headers: Enabled`);
  console.log(`Rate limiting: Enabled`);
  console.log(`CORS: ${process.env.NODE_ENV === 'production' ? 'Restricted' : 'Development mode'}`);
});

// Graceful shutdown handler
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = { app, server };

# Security Improvements for Express.js Application

## Critical Issues in Original app.js

### 1. **No Input Validation**
- **Risk**: Injection attacks, malformed data causing crashes
- **Fix**: Added parameter validation for `/users` endpoint
- **Example**: 
  ```javascript
  // Before: No validation
  const { page, limit } = req.query;

  // After: Comprehensive validation
  const pageNum = parseInt(page);
  if (isNaN(pageNum) || pageNum < 1) {
    throw new Error('Invalid page parameter');
  }
  ```

### 2. **Missing Security Headers**
- **Risk**: XSS attacks, clickjacking, MIME type sniffing
- **Fix**: Added Helmet middleware
- **Headers added**:
  - `X-Frame-Options: DENY` (prevents clickjacking)
  - `X-Content-Type-Options: nosniff` (prevents MIME sniffing)
  - `X-XSS-Protection: 1; mode=block` (XSS protection)
  - `Strict-Transport-Security` (HTTPS enforcement)
  - `Content-Security-Policy` (CSP)

### 3. **No Rate Limiting**
- **Risk**: DoS/DDoS attacks, brute force attacks
- **Fix**: Added express-rate-limit
- **Configuration**: 100 requests per 15 minutes per IP

### 4. **No CORS Configuration**
- **Risk**: Cross-origin attacks, CSRF
- **Fix**: Added CORS middleware with environment-specific origins

### 5. **No Error Handling**
- **Risk**: Information leakage, service disruption
- **Fix**: Added global error handler with proper logging

### 6. **No Request Size Limiting**
- **Risk**: Memory exhaustion attacks
- **Fix**: Added 10KB request size limits

## Additional Security Measures Implemented

### 1. **XSS Protection**
```javascript
app.use(xss()); // Sanitizes user input against XSS
```

### 2. **NoSQL Injection Protection**
```javascript
app.use(mongoSanitize()); // Removes MongoDB operators from input
```

### 3. **HTTP Parameter Pollution Protection**
```javascript
app.use(hpp()); // Prevents parameter pollution attacks
```

### 4. **Response Compression**
```javascript
app.use(compression()); // Reduces bandwidth usage
```

### 5. **Environment Variable Security**
- **Fix**: Proper .env handling with dotenv
- **Security**: Sensitive data separated from code

### 6. **Graceful Shutdown**
- **Benefit**: Prevents data corruption on shutdown
- **Implementation**: Handles SIGTERM and SIGINT signals

### 7. **Unhandled Rejection/Exception Handling**
- **Risk**: Crashes from uncaught errors
- **Fix**: Global handlers with production-safe responses

## Input Validation Best Practices

### 1. **Always Validate Inputs**
```javascript
// BAD: No validation
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // Direct use of userId without validation
});

// GOOD: Comprehensive validation
app.get('/users/:id', (req, res) => {
  const userId = parseInt(req.params.id);

  // Validate type
  if (isNaN(userId)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Validate range
  if (userId < 1 || userId > 1000000) {
    return res.status(400).json({ error: 'User ID out of valid range' });
  }

  // Proceed with validated input
});
```

### 2. **Use Whitelists, Not Blacklists**
```javascript
// BAD: Blacklist approach (can be bypassed)
const dangerousChars = ['<', '>', 'script'];
if (dangerousChars.some(char => input.includes(char))) {
  // reject input
}

// GOOD: Whitelist approach (safer)
const allowedChars = /^[a-zA-Z0-9\s@.-]+$/;
if (!allowedChars.test(input)) {
  // reject input
}
```

### 3. **Sanitize Output**
```javascript
// Prevent accidental data leakage
const sanitizedUsers = users.map(user => ({
  id: user.id,
  name: user.name,
  // Mask sensitive data in production
  email: process.env.NODE_ENV === 'production' 
    ? user.email.replace(/(?<=.).(?=.*@)/g, '*')
    : user.email
}));
```

## Error Handling Best Practices

### 1. **Structured Error Responses**
```javascript
res.status(400).json({
  success: false,
  error: 'Validation failed',
  code: 'VALIDATION_ERROR',
  details: {
    field: 'email',
    message: 'Invalid email format'
  }
});
```

### 2. **No Information Leakage in Production**
```javascript
const errorMessage = process.env.NODE_ENV === 'production' 
  ? statusCode === 500 ? 'Internal server error' : err.message
  : err.message;
```

### 3. **Comprehensive Logging**
```javascript
console.error('Application error:', {
  message: err.message,
  stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  path: req.path,
  method: req.method,
  timestamp: new Date().toISOString()
});
```

## Security Configuration Checklist

### Required Dependencies:
- [x] `helmet` - Security headers
- [x] `express-rate-limit` - Rate limiting
- [x] `xss-clean` - XSS protection
- [x] `hpp` - Parameter pollution protection
- [x] `cors` - CORS configuration
