// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const compression = require('compression');

const app = express();

// =============== SECURITY MIDDLEWARE ===============

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Enable CORS with safe defaults
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:8080'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});

// Apply to all requests
app.use(limiter);

// More strict limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.'
});

// 4. Request logging (use 'combined' format in production)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Compression for responses
app.use(compression());

// 6. Body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// =============== VALIDATION HELPER FUNCTIONS ===============

const validation = {
  // Input sanitization function
  sanitizeInput: (input) => {
    if (typeof input !== 'string') return input;
    // Remove potentially dangerous characters
    return input
      .replace(/[<>]/g, '') // Remove HTML tags
      .replace(/javascript:/gi, '') // Remove javascript: protocol
      .replace(/on\w+=/gi, '') // Remove event handlers
      .trim();
  },

  // Validate email format
  isValidEmail: (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email) && email.length <= 254;
  },

  // Validate numeric ID
  isValidId: (id) => {
    const numId = Number(id);
    return !isNaN(numId) && Number.isInteger(numId) && numId > 0;
  },

  // Validate string length and content
  isValidString: (str, options = {}) => {
    if (typeof str !== 'string') return false;

    const { 
      minLength = 1, 
      maxLength = 255, 
      allowNumbers = true, 
      allowSpecial = false 
    } = options;

    if (str.length < minLength || str.length > maxLength) return false;

    // Basic character validation
    const regex = allowSpecial 
      ? /^[a-zA-Z0-9\s\-_.,!?@]+$/ 
      : /^[a-zA-Z0-9\s]+$/;

    if (!allowNumbers) {
      return /^[a-zA-Z\s]+$/.test(str);
    }

    return regex.test(str);
  }
};

// =============== ENHANCED ROUTES WITH VALIDATION ===============

// Health endpoint with error simulation
app.get('/health', (req, res) => {
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { limit, offset } = req.query;

    if (limit && !validation.isValidId(limit)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter',
        message: 'Limit must be a positive integer'
      });
    }

    if (offset && !validation.isValidId(offset)) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter',
        message: 'Offset must be a positive integer'
      });
    }

    // Sanitize response data (in real app, this would come from DB)
    const users = [
      { 
        id: 1, 
        name: validation.sanitizeInput('Alice'), 
        email: validation.sanitizeInput('alice@example.com') 
      },
      { 
        id: 2, 
        name: validation.sanitizeInput('Bob'), 
        email: validation.sanitizeInput('bob@example.com') 
      },
    ];

    // Add pagination metadata
    const response = {
      data: users,
      meta: {
        count: users.length,
        timestamp: new Date().toISOString(),
        ...(limit && { limit: parseInt(limit) }),
        ...(offset && { offset: parseInt(offset) })
      }
    };

    res.json(response);

  } catch (error) {
    // Log error (in production, use Winston or other logging library)
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' 
        ? 'Please try again later' 
        : error.message
    });
  }
});

// Example user creation endpoint with validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || !email) {
      return res.status(400).json({ 
        error: 'Missing required fields',
        required: ['name', 'email']
      });
    }

    if (!validation.isValidString(name, { maxLength: 100 })) {
      return res.status(400).json({ 
        error: 'Invalid name',
        message: 'Name must be 1-100 alphanumeric characters'
      });
    }

    if (!validation.isValidEmail(email)) {
      return res.status(400).json({ 
        error: 'Invalid email',
        message: 'Please provide a valid email address'
      });
    }

    // Sanitize inputs
    const sanitizedName = validation.sanitizeInput(name);
    const sanitizedEmail = validation.sanitizeInput(email);

    // In real app: save to database
    const newUser = {
      id: 3,
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });

  } catch (error) {
    console.error('Error in POST /users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' 
        ? 'Failed to create user' 
        : error.message
    });
  }
});

// =============== ERROR HANDLING MIDDLEWARE ===============

// 404 Not Found handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Security: Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production'
    ? 'An unexpected error occurred'
    : err.message || 'Internal server error';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: message,
    ...(process.env.NODE_ENV !== 'production' && { 
      stack: err.stack 
    }),
    timestamp: new Date().toISOString()
  });
});

// =============== SERVER SETUP ===============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Handle uncaught exceptions and unhandled rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to exit and restart
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

const server = app.listen(PORT, HOST, () => {
  const address = server.address();
  console.log(`Server running at http://${address.address}:${address.port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const shutdown = () => {
  console.log('Shutting down server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Force shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

