// Secure Express.js application with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const { v4: uuidv4 } = require('uuid'); // For request ID generation

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// 2. CORS configuration (restrict to trusted origins)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later.',
    timestamp: new Date().toISOString(),
  },
});

app.use(limiter);

// 4. Request ID for logging and tracing
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===== INPUT VALIDATION MIDDLEWARE =====

// Custom sanitization middleware
app.use((req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim().replace(/[<>]/g, '');
      }
    });
  }

  // Sanitize body parameters
  if (req.body && typeof req.body === 'object') {
    const sanitizeObject = (obj) => {
      Object.keys(obj).forEach(key => {
        if (typeof obj[key] === 'string') {
          obj[key] = obj[key].trim().replace(/[<>]/g, '');
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
          sanitizeObject(obj[key]);
        }
      });
    };
    sanitizeObject(req.body);
  }

  next();
});

// ===== ERROR HANDLING MIDDLEWARE =====

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode, details = null) {
    super(message);
    this.statusCode = statusCode;
    this.details = details;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Request validation middleware
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        requestId: req.id,
        timestamp: new Date().toISOString(),
        details: errors.array(),
      });
    }

    next();
  };
};

// ===== ROUTES WITH VALIDATION =====

// Health check endpoint with query parameter validation
app.get('/health', 
  validateRequest([
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
  ]),
  (req, res) => {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id,
    };

    if (req.query.detailed === 'true') {
      Object.assign(response, {
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage(),
        environment: process.env.NODE_ENV || 'development',
      });
    }

    res.json(response);
  }
);

// Users endpoint with pagination and filtering validation
app.get('/users',
  validateRequest([
    query('page').optional().isInt({ min: 1 }).withMessage('page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('search').optional().isString().isLength({ max: 100 }).withMessage('search must be a string (max 100 chars)'),
  ]),
  asyncHandler(async (req, res) => {
    const { page = 1, limit = 10, search } = req.query;

    // Simulate database query with error handling
    try {
      // In a real application, this would be a database query
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
        { id: 2, name: 'Bob', email: 'bob@example.com', active: true },
      ];

      // Filter users if search parameter is provided
      let filteredUsers = users;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) || 
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit),
        },
        requestId: req.id,
        timestamp: new Date().toISOString(),
      });

    } catch (error) {
      // Log error for monitoring
      console.error(`[${req.id}] Error fetching users:`, error);
      throw new AppError('Failed to fetch users', 500, { 
        originalError: process.env.NODE_ENV === 'development' ? error.message : undefined 
      });
    }
  })
);

// User creation endpoint with comprehensive validation
app.post('/users',
  validateRequest([
    body('name').isString().trim().isLength({ min: 2, max: 50 }).withMessage('name must be 2-50 characters'),
    body('email').isEmail().normalizeEmail().withMessage('valid email is required'),
    body('age').optional().isInt({ min: 18, max: 120 }).withMessage('age must be between 18 and 120'),
  ]),
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Check for duplicate email (simulated)
    const existingUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const emailExists = existingUsers.some(user => user.email === email);
    if (emailExists) {
      throw new AppError('Email already exists', 409);
    }

    // Simulate user creation
    const newUser = {
      id: existingUsers.length + 1,
      name,
      email,
      age: age || null,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
      requestId: req.id,
      timestamp: new Date().toISOString(),
    });
  })
);

// User detail endpoint with parameter validation
app.get('/users/:id',
  validateRequest([
    query('id').isInt({ min: 1 }).withMessage('user ID must be a positive integer'),
  ]),
  asyncHandler(async (req, res) => {
    const userId = parseInt(req.params.id);

    if (isNaN(userId) || userId <= 0) {
      throw new AppError('Invalid user ID', 400);
    }

    // Simulate database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json({
      data: user,
      requestId: req.id,
      timestamp: new Date().toISOString(),
    });
  })
);

// ===== ERROR HANDLING MIDDLEWARE =====

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Route ${req.method} ${req.originalUrl} not found`, 404));
});

// Global error handler
app.use((error, req, res, next) => {
  // Log error
  console.error(`[${req.id || 'unknown'}] Error:`, {
    message: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Set default values
  const statusCode = error.statusCode || 500;
  const message = error.isOperational ? error.message : 'Internal server error';

  // Send error response
  res.status(statusCode).json({
    error: message,
    requestId: req.id,
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV === 'development' && {
      details: error.details,
      stack: error.stack,
    }),
  });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown
const shutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  // Close server
  server.close(() => {
    console.log('HTTP server closed');

    // Close database connections, etc.
    console.log('Graceful shutdown completed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  throw reason;
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

