// Enhanced app.js with essential security improvements

const express = require('express');
const app = express();

// ===== BASIC SECURITY MIDDLEWARE =====

// 1. Basic security headers
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Basic XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Don't expose server information
  res.removeHeader('X-Powered-By');

  next();
});

// 2. Body parsing with size limit
app.use(express.json({ limit: '10kb' }));

// 3. Basic input sanitization
app.use((req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
        // Remove potentially dangerous characters
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    });
  }

  next();
});

// ===== ERROR HANDLING =====

// Custom error handler
const handleErrors = (fn) => {
  return async (req, res, next) => {
    try {
      await fn(req, res, next);
    } catch (error) {
      console.error(`Error: ${error.message}`, {
        url: req.originalUrl,
        method: req.method,
        ip: req.ip,
      });

      const statusCode = error.statusCode || 500;
      const message = statusCode === 500 ? 'Internal server error' : error.message;

      res.status(statusCode).json({
        error: message,
        timestamp: new Date().toISOString(),
      });
    }
  };
};

// ===== ENHANCED ROUTES =====

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

app.get('/users', handleErrors(async (req, res) => {
  // Basic query parameter validation
  const { page = 1, limit = 10 } = req.query;

  // Validate numeric parameters
  const pageNum = parseInt(page);
  const limitNum = parseInt(limit);

  if (isNaN(pageNum) || pageNum < 1) {
    const error = new Error('Page must be a positive integer');
    error.statusCode = 400;
    throw error;
  }

  if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
    const error = new Error('Limit must be between 1 and 100');
    error.statusCode = 400;
    throw error;
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: users,
    pagination: {
      page: pageNum,
      limit: limitNum,
      total: users.length,
    },
    timestamp: new Date().toISOString(),
  });
}));

app.get('/users/:id', handleErrors(async (req, res) => {
  const userId = parseInt(req.params.id);

  // Validate ID parameter
  if (isNaN(userId) || userId <= 0) {
    const error = new Error('Invalid user ID');
    error.statusCode = 400;
    throw error;
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    const error = new Error('User not found');
    error.statusCode = 404;
    throw error;
  }

  res.json(user);
}));

// POST endpoint with basic validation
app.post('/users', handleErrors(async (req, res) => {
  const { name, email } = req.body;

  // Basic input validation
  if (!name || typeof name !== 'string' || name.trim().length < 2) {
    const error = new Error('Name is required and must be at least 2 characters');
    error.statusCode = 400;
    throw error;
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    const error = new Error('Valid email is required');
    error.statusCode = 400;
    throw error;
  }

  // Sanitize inputs
  const sanitizedName = name.trim().replace(/[<>]/g, '');
  const sanitizedEmail = email.trim().replace(/[<>]/g, '');

  // Check for existing user (simulated)
