// Enhanced Express application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();
const PORT = process.env.PORT || 3000;

// Configure Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Security middleware - always use helmet first
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:8080'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skipSuccessfulRequests: false,
  skip: (req) => req.ip === '127.0.0.1' // Optional: skip localhost
});

// Apply rate limiting to all requests
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      url: req.url,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      statusCode: res.statusCode,
      duration,
      timestamp: new Date().toISOString()
    });
  });
  next();
});

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  const sanitize = (obj) => {
    if (!obj) return obj;
    if (typeof obj === 'string') {
      // Remove potentially dangerous characters
      return obj.replace(/[<>'"`]/g, '');
    }
    if (Array.isArray(obj)) {
      return obj.map(sanitize);
    }
    if (typeof obj === 'object') {
      const sanitized = {};
      for (const key in obj) {
        sanitized[key] = sanitize(obj[key]);
      }
      return sanitized;
    }
    return obj;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);
  if (req.params) req.params = sanitize(req.params);

  next();
};

app.use(sanitizeInput);

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack trace in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
    status: 'error',
    timestamp: new Date().toISOString()
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(err.statusCode || 500).json(errorResponse);
};

// Validation middleware
const validateInput = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const errorMessages = errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }));

      logger.warn({
        message: 'Validation failed',
        errors: errorMessages,
        url: req.url,
        ip: req.ip,
        timestamp: new Date().toISOString()
      });

      return res.status(400).json({
        error: 'Validation failed',
        details: errorMessages,
        status: 'error',
        timestamp: new Date().toISOString()
      });
    }

    next();
  };
};

// Health endpoint with validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], validateInput([
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
]), (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    if (req.query.detailed === 'true') {
      healthData.process = {
        pid: process.pid,
        version: process.version,
        platform: process.platform
      };
    }

    res.json({
      status: 'ok',
      data: healthData
    });
  } catch (error) {
    logger.error(`Health check failed: ${error.message}`);
    res.status(503).json({
      status: 'error',
      error: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with comprehensive validation and security
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a positive integer'),
  query('fields').optional().matches(/^[a-z,]+$/).withMessage('fields must contain only lowercase letters separated by commas')
], validateInput([
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a positive integer')
]), (req, res, next) => {
  try {
    // Mock data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user', createdAt: '2024-01-01T00:00:00Z' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user', createdAt: '2024-01-02T00:00:00Z' },
    ];

    // Apply pagination
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const paginatedUsers = users.slice(offset, offset + limit);

    // Field selection (prevent data exposure)
    let responseUsers = paginatedUsers;
    if (req.query.fields) {
      const allowedFields = req.query.fields.split(',');
      responseUsers = paginatedUsers.map(user => {
        const filtered = {};
        allowedFields.forEach(field => {
          if (user[field] !== undefined) {
            filtered[field] = user[field];
          }
        });
        return filtered;
      });
    }

    // Remove sensitive data before sending
    const safeUsers = responseUsers.map(user => {
      const { email, ...safeUser } = user;
      return safeUser;
    });

    res.json({
      status: 'ok',
      data: {
        users: safeUsers,
        pagination: {
          total: users.length,
          limit,
          offset,
          hasMore: offset + limit < users.length
        }
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Example POST endpoint with validation
app.post('/users', [
  body('name').notEmpty().trim().escape().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
  body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
  body('role').optional().isIn(['user', 'admin']).withMessage('Role must be either user or admin')
], validateInput([
  body('name').notEmpty().trim().escape().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
  body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
  body('role').optional().isIn(['user', 'admin']).withMessage('Role must be either user or admin')
]), (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, this would save to a database
    const newUser = {
      id: Math.floor(Math.random() * 1000) + 3, // Simulated ID
      name,
      email,
      role,
      createdAt: new Date().toISOString()
    };

    logger.info(`New user created: ${email}`);

    res.status(201).json({
      status: 'success',
      data: {
        user: {
          id: newUser.id,
          name: newUser.name,
          role: newUser.role
        }
      },
      message: 'User created successfully',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  logger.warn({
    message: 'Route not found',
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  res.status(404).json({
    error: 'Route not found',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    status: 'error',
    timestamp: new Date().toISOString()
  });
});

// Apply error handling middleware last
app.use(errorHandler);

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received, starting graceful shutdown`);

  setTimeout(() => {
    logger.info('Shutdown timeout reached, forcing exit');
    process.exit(1);
  }, 10000);

  if (server) {
    server.close(() => {
      logger.info('HTTP server closed');
      process.exit(0);
    });
  }
};

// Start server
const server = app.listen(PORT, () => {
  logger.info(`Server running securely on port ${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to restart the process
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

module.exports = app;

