// Security feature tests for the improved app.js

const request = require('supertest');
const app = require('./app_improved');

describe('Security Features Tests', () => {

  describe('Error Handling', () => {
    it('should return 404 for undefined routes', async () => {
      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body).toHaveProperty('error', 'Route not found');
      expect(response.body).toHaveProperty('status', 'error');
    });

    it('should handle malformed JSON gracefully', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'application/json')
        .send('{ invalid json }')
        .expect(400);

      expect(response.body).toHaveProperty('status', 'error');
    });
  });

  describe('Input Validation', () => {
    it('should validate query parameters for /users', async () => {
      const response = await request(app)
        .get('/users?limit=200') // limit exceeds maximum
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
      expect(response.body.details[0]).toHaveProperty('field', 'limit');
    });

    it('should validate email format for POST /users', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'Test User',
          email: 'invalid-email'
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should sanitize input with dangerous characters', async () => {
      const response = await request(app)
        .get('/users?fields=id,name<script>alert("xss")</script>')
        .expect(400);

      // The sanitizer should have removed dangerous characters
      expect(response.body).toHaveProperty('error', 'Validation failed');
    });
  });

  describe('Security Headers', () => {
    it('should include security headers', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Check for important security headers
      expect(response.headers).toHaveProperty('x-powered-by', undefined); // Should be hidden
      expect(response.headers).toHaveProperty('x-content-type-options', 'nosniff');
    });
  });

  describe('Data Protection', () => {
    it('should not expose email in GET /users response', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      const user = response.body.data.users[0];
      expect(user).not.toHaveProperty('email');
      expect(user).toHaveProperty('id');
      expect(user).toHaveProperty('name');
    });

    it('should limit field selection', async () => {
      const response = await request(app)
        .get('/users?fields=id,name')
        .expect(200);

      const user = response.body.data.users[0];
      expect(Object.keys(user)).toEqual(['id', 'name']);
      expect(user).not.toHaveProperty('email');
      expect(user).not.toHaveProperty('role');
    });
  });

  describe('Rate Limiting', () => {
    it('should return rate limit headers', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers).toHaveProperty('ratelimit-limit');
      expect(response.headers).toHaveProperty('ratelimit-remaining');
    });
  });

  describe('CORS Configuration', () => {
    it('should include CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:8080')
        .expect(200);

      expect(response.headers).toHaveProperty('access-control-allow-origin');
    });
  });

  describe('Health Endpoint', () => {
    it('should validate detailed parameter', async () => {
      const response = await request(app)
        .get('/health?detailed=not-a-boolean')
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should include process info when detailed=true', async () => {
      const response = await request(app)
        .get('/health?detailed=true')
        .expect(200);

      expect(response.body.data).toHaveProperty('process');
    });
  });
});

// Helper function for demonstration
function expect(obj) {
  return {
    toHaveProperty: function(prop, value) {
      if (!obj.hasOwnProperty(prop)) {
        throw new Error(`Expected object to have property ${prop}`);
      }
      if (value !== undefined && obj[prop] !== value) {
        throw new Error(`Expected ${obj[prop]} to equal ${value}`);
      }
      return this;
    },
    toEqual: function(expected) {
      if (JSON.stringify(obj) !== JSON.stringify(expected)) {
        throw new Error(`Expected ${JSON.stringify(obj)} to equal ${JSON.stringify(expected)}`);
      }
      return this;
    }
  };
}

