// Secure Express.js Application with Comprehensive Error Handling and Security Best Practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// Security Middleware Configuration
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
}));

// Configure CORS based on environment
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : '*',
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// Request Parsing with Size Limits
app.use(express.json({ limit: '10kb' })); // Prevent JSON parsing attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.NODE_ENV === 'production' ? 100 : 500, // requests per window per IP
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// Request Logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Structured Error Handler Class
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    Error.captureStackTrace(this, this.constructor);
  }
}

// Validation Utility Functions
const validate = (validations) => {
  return async (req, res, next) => {
    try {
      await Promise.all(validations.map(validation => validation.run(req)));
      const errors = validationResult(req);

      if (!errors.isEmpty()) {
        const errorMessages = errors.array().map(err => ({
          field: err.param,
          message: err.msg,
          location: err.location
        }));

        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors: errorMessages
        });
      }

      next();
    } catch (error) {
      next(error);
    }
  };
};

// Sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Simple sanitization examples - expand based on your needs
  Object.keys(req.body).forEach(key => {
    if (typeof req.body[key] === 'string') {
      // Remove potentially dangerous characters
      req.body[key] = req.body[key].replace(/[<>]/g, '');
    }
  });

  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].replace(/[<>]/g, '');
    }
  });

  next();
};

// Health check endpoint with validation
app.get('/health', sanitizeInput, (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error during health check'
    });
  }
});

// Users endpoint with comprehensive validation and error handling
app.get('/users', sanitizeInput, [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  body('sort').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field'),
], validate, async (req, res, next) => {
  try {
    // In a real app, this would come from a database
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    // Apply pagination if requested
    const limit = parseInt(req.query.limit) || users.length;
    const offset = parseInt(req.query.offset) || 0;
    const paginatedUsers = users.slice(offset, offset + limit);

    // Apply sorting if requested
    if (req.query.sort) {
      paginatedUsers.sort((a, b) => a[req.query.sort].localeCompare(b[req.query.sort]));
    }

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    next(new AppError('Unable to fetch users', 500));
  }
});

// Example POST endpoint with validation
app.post('/users', sanitizeInput, [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),

  body('age').optional()
    .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),
], validate, async (req, res, next) => {
  try {
    // In a real app, you would save to database here
    const newUser = {
      id: Date.now(), // Simple ID generation - use proper UUID in production
      ...req.body,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      status: 'success',
      data: newUser,
      message: 'User created successfully'
    });

  } catch (error) {
    console.error('Error creating user:', error);
    next(new AppError('Unable to create user', 500));
  }
});

// 404 Handler
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global Error Handling Middleware
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const status = err.status || 'error';

  // Log error with context
  console.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV
  });

  // Production vs development error responses
  const errorResponse = {
    status,
    message: err.message
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.originalError = err;
  }

  // Don't leak internal errors in production
  if (process.env.NODE_ENV === 'production' && !err.isOperational) {
    errorResponse.message = 'Something went wrong';
  }

  // TODO: Send error to monitoring service (e.g., Sentry, Datadog)

  res.status(statusCode).json(errorResponse);
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');

  // Close server and clean up resources
  server.close(() => {
    console.log('HTTP server closed');

    // TODO: Close database connections, message queues, etc.

    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle different shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Unhandled rejection/exception handling
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // TODO: Send to monitoring service
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // TODO: Send to monitoring service
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

module.exports = { app, server };

// Security Tests for Express Application
// Run with: node test-security.js

