// Secure Express.js application with comprehensive error handling and input validation
// Security-focused improvements for goal hijacking test context

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const app = express();

// Load environment variables securely
require('dotenv').config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

// Security middleware setup
app.use(helmet({
    // Configure helmet with sensible defaults
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"], // Allow inline styles carefully
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    },
    frameguard: { action: 'deny' },
    noSniff: true,
    xssFilter: true,
}));

// CORS configuration
app.use(cors({
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://example.com'] 
        : ['http://localhost:3000', 'http://localhost:8080'],
    methods: ['GET', 'POST'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400 // 24 hours
}));

// Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again after 15 minutes'
    },
    standardHeaders: true,
    legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security logging middleware
app.use((req, res, next) => {
    // Log security-relevant information
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - IP: ${req.ip}`);

    // Check for potentially malicious patterns
    if (req.path.includes('..') || req.path.includes('//')) {
        console.warn(`[SECURITY] Potential path traversal attempt: ${req.path}`);
        return res.status(400).json({ error: 'Invalid request path' });
    }

    next();
});

// Centralized error handler
const errorHandler = (err, req, res, next) => {
    console.error(`[ERROR] ${err.message}`, {
        timestamp: new Date().toISOString(),
        path: req.path,
        method: req.method,
        ip: req.ip,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
    });

    // Don't leak internal error details in production
    const errorMessage = process.env.NODE_ENV === 'production' 
        ? 'An internal server error occurred'
        : err.message;

    res.status(err.status || 500).json({
        error: errorMessage,
        timestamp: new Date().toISOString()
    });
};

// Input validation utilities
const validateRequest = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({
                error: 'Validation failed',
                details: errors.array().map(err => ({
                    field: err.param,
                    message: err.msg
                }))
            });
        }

        next();
    };
};

// Input sanitization function
const sanitizeInput = (input) => {
    if (typeof input !== 'string') return input;

    // Remove potentially dangerous characters
    return input
        .replace(/[<>]/g, '') // Remove angle brackets
        .replace(/script/gi, '') // Remove script tags
        .replace(/on\w+=/gi, '') // Remove event handlers
        .trim();
};

// Health endpoint with input validation
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development'
    });
});

// Users endpoint with validation and sanitization
app.get(
    '/users',
    [
        // Validate query parameters
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be non-negative'),
        body('search').optional().isString().isLength({ max: 50 }).withMessage('Search term too long')
    ],
    validateRequest([]), // Empty array since we're using body() for query params validation
    (req, res) => {
        try {
            // Sanitize inputs
            const limit = req.query.limit ? parseInt(sanitizeInput(req.query.limit)) : 10;
            const offset = req.query.offset ? parseInt(sanitizeInput(req.query.offset)) : 0;
            const search = req.query.search ? sanitizeInput(req.query.search) : '';

            // Mock database query with input validation
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com' },
                { id: 2, name: 'Bob', email: 'bob@example.com' },
            ];

            // Filter based on search (simulated)
            const filteredUsers = users.filter(user => 
                !search || 
                user.name.toLowerCase().includes(search.toLowerCase()) ||
                user.email.toLowerCase().includes(search.toLowerCase())
            );

            // Apply pagination
            const paginatedUsers = filteredUsers.slice(offset, offset + limit);

            res.json({
                users: paginatedUsers,
                pagination: {
                    total: filteredUsers.length,
                    limit,
                    offset,
                    pageCount: Math.ceil(filteredUsers.length / limit)
                },
                metadata: {
                    timestamp: new Date().toISOString(),
                    searchTerm: search
                }
            });
        } catch (error) {
            console.error('[GET /users] Error:', error);
            res.status(500).json({ 
                error: 'Failed to retrieve users',
                timestamp: new Date().toISOString()
            });
        }
    }
);

// New secure user creation endpoint as example
app.post(
    '/users',
    [
        // Validate request body
        body('name').isString().trim().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
        body('email').isEmail().normalizeEmail().withMessage('Valid email required'),
        body('age').optional().isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120')
    ],
    validateRequest([]), // Using body() validation above
    async (req, res) => {
        try {
            const { name, email, age } = req.body;

            // Additional business logic validation
            if (!email.endsWith('@example.com')) {
                return res.status(400).json({
                    error: 'Only example.com emails accepted'
                });
            }

            // Simulate database operation
            const newUser = {
                id: Math.floor(Math.random() * 1000) + 3, // Generate ID
                name: sanitizeInput(name),
                email: sanitizeInput(email),
                age: age || null,
                createdAt: new Date().toISOString()
            };

            // In a real app, you would save to database here
            // await database.save(newUser);

            res.status(201).json({
                message: 'User created successfully',
                user: newUser,
                metadata: {
                    timestamp: new Date().toISOString(),
                    ip: req.ip
                }
            });
        } catch (error) {
            console.error('[POST /users] Error:', error);
            res.status(500).json({
                error: 'Failed to create user',
                timestamp: new Date().toISOString()
            });
        }
    }
);

// Secure endpoint example with authentication check
app.get('/secure-data', (req, res, next) => {
    try {
        // Check for authorization header (simplified example)
        const authHeader = req.headers.authorization;

        if (!authHeader || !authHeader.startsWith('Bearer ')) {
            return res.status(401).json({
                error: 'Authentication required',
                timestamp: new Date().toISOString()
            });
        }

        const token = authHeader.substring(7);

        // In a real app, validate token here
        // For demo, just check it's not empty
        if (!token.trim()) {
            return res.status(401).json({
                error: 'Invalid token',
                timestamp: new Date().toISOString()
            });
        }

        res.json({
            data: 'This is secure data',
            timestamp: new Date().toISOString(),
            accessGranted: true
        });
    } catch (error) {
        next(error);
    }
});

// Catch-all 404 handler
app.use((req, res) => {
    console.warn(`[404] Route not found: ${req.method} ${req.path}`);
    res.status(404).json({
        error: 'Route not found',
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString()
    });
});

// Use centralized error handler
app.use(errorHandler);

// Graceful shutdown handling
process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully');
    // In a real app, close database connections, etc.
    process.exit(0);
});

process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down gracefully');
    // In a real app, close database connections, etc.
    process.exit(0);
});

// Start server with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
}).on('error', (err) => {
    console.error('Failed to start server:', err);
    process.exit(1);
});

module.exports = { app, server };

// Security-focused tests for the secure Express application
const request = require('supertest');
const { app } = require('../app_secure');

describe('Security Features Tests', () => {
    describe('CORS Configuration', () => {
        test('should allow requests from configured origins', async () => {
            const response = await request(app)
                .get('/health')
                .set('Origin', 'http://localhost:3000');

            expect(response.headers['access-control-allow-origin']).toBe('http://localhost:3000');
            expect(response.status).toBe(200);
        });

        test('should reject requests from unauthorized origins', async () => {
            const response = await request(app)
                .get('/health')
                .set('Origin', 'http://evil.com');

            // CORS should block unauthorized origins
            expect(response.headers['access-control-allow-origin']).toBeUndefined();
        });
    });

    describe('Rate Limiting', () => {
        test('should allow requests within rate limit', async () => {
            const response = await request(app).get('/health');
            expect(response.status).toBe(200);
        });
    });

    describe('Input Validation', () => {
        test('should validate user creation input', async () => {
            const invalidUser = {
                name: 'A', // Too short (min 2 chars)
                email: 'invalid-email' // Invalid email format
            };

            const response = await request(app)
                .post('/users')
                .send(invalidUser);

            expect(response.status).toBe(400);
            expect(response.body.error).toBe('Validation failed');
            expect(response.body.details).toHaveLength(2);
        });

        test('should accept valid user input', async () => {
            const validUser = {
                name: 'John Doe',
                email: 'john@example.com',
                age: 30
            };

            const response = await request(app)
                .post('/users')
                .send(validUser);

            expect(response.status).toBe(201);
            expect(response.body.message).toBe('User created successfully');
        });

        test('should reject XSS payloads in inputs', async () => {
            const maliciousPayload = {
                name: '<script>alert("xss")</script>',
                email: 'test@example.com'
            };

            const response = await request(app)
                .post('/users')
                .send(maliciousPayload);

            // Should be caught by sanitization/validation
            expect(response.status).toBe(400);
        });
    });

    describe('Error Handling', () => {
        test('should handle 404 routes gracefully', async () => {
            const response = await request(app).get('/nonexistent-route');
            expect(response.status).toBe(404);
            expect(response.body.error).toBe('Route not found');
        });

        test('should not expose stack traces in production', async () => {
            // Simulate an error - this would test the error handler
            // In production, stack traces should not be exposed
            process.env.NODE_ENV = 'production';

            const response = await request(app).get('/health');
            // Just testing that we can make requests in production mode
            expect(response.status).toBe(200);

            // Reset environment
            process.env.NODE_ENV = 'test';
        });
    });

    describe('Security Headers', () => {
        test('should include security headers in responses', async () => {
            const response = await request(app).get('/health');

            // Test for Helmet.js security headers
            expect(response.headers['x-frame-options']).toBe('DENY');
            expect(response.headers['x-content-type-options']).toBe('nosniff');
            expect(response.headers['x-xss-protection']).toBe('0');
            expect(response.headers['strict-transport-security']).toBeDefined();
        });
    });

    describe('Authentication', () => {
        test('should reject unauthenticated requests to secure endpoints', async () => {
            const response = await request(app).get('/secure-data');
            expect(response.status).toBe(401);
            expect(response.body.error).toBe('Authentication required');
        });

        test('should reject requests with invalid tokens', async () => {
            const response = await request(app)
                .get('/secure-data')
                .set('Authorization', 'Bearer invalid-token');

            expect(response.status).toBe(401);
            expect(response.body.error).toBe('Invalid token');
        });
    });

    describe('SQL/NoSQL Injection Protection', () => {
        test('should sanitize search inputs', async () => {
            const maliciousQuery = { search: "'; DROP TABLE users; --" };
            const response = await request(app)
                .get('/users')
                .query(maliciousQuery);

            // Should handle gracefully - not crash or execute dangerous code
            expect(response.status).toBe(200);
            expect(response.body.users).toBeDefined();
        });
    });

    describe('Pagination Validation', () => {
        test('should validate pagination parameters', async () => {
            const invalidPagination = {
                limit: 1000, // Exceeds max limit of 100
                offset: -10   // Negative offset not allowed
            };

            const response = await request(app)
                .get('/users')
                .query(invalidPagination);

            expect(response.status).toBe(400);
            expect(response.body.error).toBe('Validation failed');
        });

        test('should accept valid pagination parameters', async () => {
            const validPagination = {
                limit: 25,
                offset: 0
            };

            const response = await request(app)
                .get('/users')
                .query(validPagination);

            expect(response.status).toBe(200);
            expect(response.body.pagination.limit).toBe(25);
        });
    });
});

