// Enhanced application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const expressListEndpoints = require('express-list-endpoints');

// Load environment variables
require('dotenv').config();

const app = express();

// Security middleware setup
// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
}));

// 3. Body parsing with limits
app.use(express.json({
  limit: '10kb' // Prevent large payload attacks
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// 4. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter);

// 5. Security middleware
app.use(hpp()); // Protect against HTTP Parameter Pollution attacks
app.use(mongoSanitize()); // Sanitize data against NoSQL injection
app.use(xss()); // Sanitize user input against XSS attacks

// Custom middleware for request logging
app.use((req, res, next) => {
  const start = Date.now();
  const originalSend = res.send;
  const requestId = require('crypto').randomBytes(8).toString('hex');

  res.send = function(body) {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      requestId,
      method: req.method,
      path: req.path,
      ip: req.ip || req.connection.remoteAddress,
      userAgent: req.get('User-Agent'),
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      query: Object.keys(req.query).length > 0 ? req.query : undefined,
      params: Object.keys(req.params).length > 0 ? req.params : undefined
    });
    originalSend.call(this, body);
  };
  next();
});

// Input validation middleware
const validateUserId = (req, res, next) => {
  const userId = req.params.id;
  if (userId) {
    // Validate user ID format
    const idRegex = /^[1-9]\d*$/; // Positive integer
    if (!idRegex.test(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID format',
        message: 'User ID must be a positive integer'
      });
    }

    // Check if ID is within reasonable bounds
    const idNum = parseInt(userId, 10);
    if (idNum > 1000000) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID exceeds maximum allowed value'
      });
    }
  }
  next();
};

// Health endpoint with validation
app.get('/health', (req, res) => {
  try {
    const healthCheck = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    };

    // Additional health checks can be added here
    // e.g., database connectivity, external service status

    res.json(healthCheck);
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(503).json({
      status: 'unhealthy',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with enhanced security
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    // Sanitize and validate limit parameter
    let sanitizedLimit = 10; // Default
    if (limit) {
      const limitNum = parseInt(limit, 10);
      if (!isNaN(limitNum) && limitNum > 0 && limitNum <= 100) {
        sanitizedLimit = limitNum;
      } else {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Sanitize and validate offset parameter
    let sanitizedOffset = 0; // Default
    if (offset) {
      const offsetNum = parseInt(offset, 10);
      if (!isNaN(offsetNum) && offsetNum >= 0) {
        sanitizedOffset = offsetNum;
      } else {
        return res.status(400).json({
          error: 'Invalid offset parameter',
          message: 'Offset must be a non-negative integer'
        });
      }
    }

    // Simulated user data (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' }
    ];

    // Apply pagination
    const paginatedUsers = users.slice(sanitizedOffset, sanitizedOffset + sanitizedLimit);

    // Remove sensitive information before sending response
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Note: role is omitted for security
    }));

    res.json({
      users: sanitizedUsers,
      pagination: {
        total: users.length,
        limit: sanitizedLimit,
        offset: sanitizedOffset,
        hasMore: (sanitizedOffset + sanitizedLimit) < users.length
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred while fetching users'
    });
  }
});

// Single user endpoint with validation
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Simulated user lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        message: `User with ID ${userId} does not exist`
      });
    }

    // Remove sensitive information
    const sanitizedUser = {
      id: user.id,
      name: user.name,
      email: user.email
    };

    res.json(sanitizedUser);

  } catch (error) {
    console.error(`Error fetching user ${req.params.id}:`, error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred while fetching the user'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine error type and respond appropriately
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    // JSON parsing error
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON payload',
      details: err.message
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    availableEndpoints: expressListEndpoints(app).map(ep => ({
      path: ep.path,
      methods: ep.methods
    }))
  });
});

// Server startup with proper error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

  // List all registered routes for debugging
  if (process.env.NODE_ENV !== 'production') {
    const endpoints = expressListEndpoints(app);
    console.log('\nRegistered endpoints:');
    endpoints.forEach(endpoint => {
      console.log(`${endpoint.methods.join(', ')} ${endpoint.path}`);
    });
  }
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

  server.close((err) => {
    if (err) {
      console.error('Error during shutdown:', err);
      process.exit(1);
    }

    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging or cleanup can go here
});

module.exports = { app, server };

// Test script to demonstrate security improvements

const http = require('http');

console.log('Testing security improvements in enhanced app.js\n');

// Test cases to demonstrate security features
const testCases = [
  {
    name: '1. Missing security headers in original app',
    description: 'Original app lacks security headers like X-Content-Type-Options, X-Frame-Options, etc.',
    original: 'http://localhost:3000/health',
    improved: 'Not applicable - headers missing in original'
  },
  {
    name: '2. Input validation for user ID',
    description: 'Original app has no input validation for route parameters',
    original: 'http://localhost:3000/users/abc (would accept invalid ID)',
    improved: 'Improved app validates ID format and returns 400 for invalid IDs'
  },
  {
    name: '3. SQL/NoSQL injection protection',
    description: 'Original app has no protection against injection attacks',
    original: 'Vulnerable to NoSQL injection if using MongoDB',
    improved: 'Uses express-mongo-sanitize to prevent NoSQL injection'
  },
  {
    name: '4. XSS protection',
    description: 'Original app has no XSS protection',
    original: 'Vulnerable to cross-site scripting attacks',
    improved: 'Uses xss-clean middleware to sanitize inputs'
  },
  {
    name: '5. Rate limiting',
    description: 'Original app has no rate limiting',
    original: 'Vulnerable to brute force and DoS attacks',
    improved: 'Implements rate limiting (100 requests per 15 minutes per IP)'
  },
  {
    name: '6. Error handling',
    description: 'Original app has limited error handling',
    original: 'Unhandled errors may crash server or expose sensitive information',
    improved: 'Comprehensive error handling middleware with proper logging'
  },
  {
    name: '7. Request logging',
    description: 'Original app has minimal logging',
    original: 'Basic console.log in server startup only',
    improved: 'Detailed request logging with request IDs, timing, and sanitized data'
  },
  {
    name: '8. CORS configuration',
    description: 'Original app has no CORS configuration',
    original: 'May accept requests from any origin',
    improved: 'Configurable CORS with allowed origins validation'
  },
  {
    name: '9. Body size limiting',
    description: 'Original app has no body size limits',
    original: 'Vulnerable to large payload attacks',
    improved: '10kb limit on JSON and URL-encoded bodies'
  },
  {
    name: '10. Graceful shutdown',
    description: 'Original app has no shutdown handling',
    original: 'May not handle termination signals properly',
    improved: 'Graceful shutdown with timeout handling'
  }
];

// Display test cases
console.log('Security Improvements Summary:');
console.log('='.repeat(80));

testCases.forEach((test, index) => {
  console.log(`\n${test.name}`);
  console.log('-'.repeat(test.name.length));
  console.log(`Description: ${test.description}`);
  console.log(`Original: ${test.original}`);
  console.log(`Improved: ${test.improved}`);
});

console.log('\n' + '='.repeat(80));
console.log('\nAdditional Security Best Practices Implemented:');
console.log('1. Helmet.js for security headers');
console.log('2. HTTP Parameter Pollution protection');
console.log('3. Non-root user execution in Docker');
console.log('4. Environment-based configuration');
