// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet()); // Sets security headers

// Configure CORS properly
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  next();
});

// Validate environment variables on startup
function validateEnvironment() {
  const requiredEnvVars = ['NODE_ENV'];
  const missingVars = [];

  requiredEnvVars.forEach(varName => {
    if (!process.env[varName]) {
      missingVars.push(varName);
    }
  });

  if (missingVars.length > 0) {
    console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
    process.exit(1);
  }
}

// Validate environment on startup
validateEnvironment();

// Input validation middleware
function validateUserId(req, res, next) {
  const userId = req.params.id || req.query.id;

  if (userId) {
    // Validate that ID is a positive integer
    const idNum = parseInt(userId);
    if (isNaN(idNum) || idNum <= 0 || !Number.isInteger(idNum)) {
      return res.status(400).json({ 
        error: 'Invalid user ID', 
        message: 'User ID must be a positive integer' 
      });
    }

    // Sanitize - ensure we're using the parsed integer
    if (req.params.id) req.params.id = idNum;
    if (req.query.id) req.query.id = idNum;
  }

  next();
}

function validateStringInput(str, fieldName, maxLength = 100) {
  if (!str) return true;

  // Check for basic injection patterns
  const dangerousPatterns = [
    /<script\b/i,
    /javascript:/i,
    /on\w+\s*=/i,
    /eval\s*\(/i,
    /alert\s*\(/i,
    /document\./i,
    /window\./i
  ];

  for (const pattern of dangerousPatterns) {
    if (pattern.test(str)) {
      return false;
    }
  }

  // Check length
  return str.length <= maxLength;
}

// Health endpoint with improved response
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version
    };

    res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      timestamp: new Date().toISOString(),
      error: 'Internal server error during health check'
    });
  }
});

// Users endpoint with parameter validation
app.get('/users', validateUserId, (req, res) => {
  try {
    // Validate query parameters if present
    const { search, limit, offset } = req.query;

    // Validate search term
    if (search && !validateStringInput(search, 'search', 50)) {
      return res.status(400).json({ 
        error: 'Invalid search parameter', 
        message: 'Search term contains potentially dangerous content' 
      });
    }

    // Validate limit and offset
    if (limit) {
      const limitNum = parseInt(limit);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter', 
          message: 'Limit must be a positive integer not exceeding 100' 
        });
      }
    }

    if (offset) {
      const offsetNum = parseInt(offset);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter', 
          message: 'Offset must be a non-negative integer' 
        });
      }
    }

    // Sample user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Apply filters if provided
    let filteredUsers = [...users];

    if (search) {
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const actualLimit = limit ? parseInt(limit) : 10;
    const actualOffset = offset ? parseInt(offset) : 0;

    const paginatedUsers = filteredUsers.slice(actualOffset, actualOffset + actualLimit);

    res.json({
      users: paginatedUsers,
      metadata: {
        total: filteredUsers.length,
        limit: actualLimit,
        offset: actualOffset,
        returned: paginatedUsers.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error', 
      message: 'Failed to retrieve users' 
    });
  }
});

// Individual user endpoint with validation
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found', 
        message: `User with ID ${userId} not found` 
      });
    }

    res.json(user);
  } catch (error) {
    console.error('User endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error', 
      message: 'Failed to retrieve user' 
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal server error', 
      message: 'Something went wrong' 
    });
  }

  res.status(500).json({ 
    error: 'Internal server error', 
    message: err.message,
    stack: err.stack 
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found', 
    message: 'The requested resource was not found' 
  });
});

// Graceful shutdown
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

function gracefulShutdown() {
  console.log('Received shutdown signal, closing server...');

  // Give ongoing requests time to complete
  setTimeout(() => {
    process.exit(0);
  }, 10000);
}

// Start server with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
}).on('error', (err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

