// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// 2. CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Production origins
    : ['http://localhost:3000', 'http://localhost:3001'], // Development origins
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request sanitization middleware
app.use((req, res, next) => {
  // Basic sanitization for query parameters and body
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].replace(/[<>]/g, ''); // Simple XSS protection
      }
    });
  }

  if (req.body && typeof req.body === 'object') {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].replace(/[<>]/g, ''); // Simple XSS protection
      }
    });
  }
  next();
});

// ====================
// ERROR HANDLING UTILITIES
// ====================

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Custom error responses based on error type
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      message: err.message,
      details: err.errors
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or missing authentication'
    });
  }

  // Default error
  const statusCode = err.statusCode || 500;
  const errorMessage = process.env.NODE_ENV === 'production'
    ? 'Something went wrong'
    : err.message;

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: errorMessage,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ====================
// VALIDATION UTILITIES
// ====================

// Input validation middleware
const validateInput = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    const error = new Error('Input validation failed');
    error.name = 'ValidationError';
    error.statusCode = 400;
    error.errors = errors.array().map(err => ({
      param: err.param,
      msg: err.msg,
      location: err.location
    }));

    return next(error);
  };
};

// ====================
// ROUTES WITH ENHANCED SECURITY
// ====================

// Health endpoint with additional security
app.get('/health', (req, res) => {
  try {
    // Validate no malicious query parameters
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Health endpoint does not accept query parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', 
  validateInput([
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  ]),
  asyncHandler(async (req, res) => {
    try {
      // Simulated database query with parameterized values
      const { limit = 10, offset = 0 } = req.query;

      // Validate numeric parameters (additional safety)
      const validatedLimit = Math.min(Math.max(parseInt(limit) || 10, 1), 100);
      const validatedOffset = Math.max(parseInt(offset) || 0, 0);

      // In a real application, you would use parameterized queries like:
      // const users = await db.query('SELECT * FROM users LIMIT $1 OFFSET $2', [validatedLimit, validatedOffset]);

      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          created_at: new Date().toISOString()
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          created_at: new Date().toISOString()
        },
      ];

      // Paginate results
      const paginatedUsers = users.slice(validatedOffset, validatedOffset + validatedLimit);

      // Sanitize output (remove sensitive data if necessary)
      const sanitizedUsers = paginatedUsers.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email // Consider masking email in production
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          total: users.length,
          limit: validatedLimit,
          offset: validatedOffset,
          hasMore: validatedOffset + validatedLimit < users.length
        }
      });

    } catch (error) {
      console.error('Error fetching users:', error);
      throw new Error('Failed to fetch users');
    }
  })
);

// New secure user creation endpoint with validation
app.post('/users',
  validateInput([
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/)
      .withMessage('Name can only contain letters and spaces'),
    body('email')
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be at least 8 characters')
      .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
      .withMessage('Password must contain at least one uppercase letter, one lowercase letter, and one number')
  ]),
  asyncHandler(async (req, res) => {
    try {
      const { name, email, password } = req.body;

      // Additional business logic validation
      if (email.includes('+')) {
        throw new Error('Plus addressing not allowed in emails');
      }

      // In a real application:
      // 1. Hash the password with bcrypt
      // 2. Check for existing user with same email
      // 3. Store in database with prepared statements

      const newUser = {
        id: Date.now(), // Use proper ID generation in production
        name,
        email,
        // Never include password in response
        created_at: new Date().toISOString()
      };

      res.status(201).json({
        message: 'User created successfully',
        user: {
          id: newUser.id,
          name: newUser.name,
          email: newUser.email
        }
      });

    } catch (error) {
      console.error('Error creating user:', error);
      throw error;
    }
  })
);

// Dynamic route with parameter validation
app.get('/users/:id', 
  validateInput([
    body('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ]),
  asyncHandler(async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Validate ID parameter
      if (isNaN(userId) || userId <= 0) {
        throw new Error('Invalid user ID');
      }

      // SQL injection protection - always use parameterized queries
      // const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

      const user = { 
        id: userId, 
        name: 'Test User', 
        email: 'test@example.com'
      };

      if (!user) {
        throw new Error('User not found');
      }

      res.json(user);

    } catch (error) {
      if (error.message === 'User not found') {
        error.statusCode = 404;
      }
      throw error;
    }
  })
);

// ====================
// SECURITY HEADERS ENDPOINT
// ====================

// Endpoint to check security headers (for testing)
app.get('/security-headers', (req, res) => {
  const headers = {
    'Content-Security-Policy': "default-src 'self'",
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY',
    'X-XSS-Protection': '1; mode=block',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'geolocation=()' // Customize based on app needs
  };

  res.json(headers);
});

// ====================
// 404 HANDLER
// ====================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    timestamp: new Date().toISOString()
  });
});

// ====================
// ERROR HANDLER (MUST BE LAST)
// ====================

app.use(errorHandler);

// ====================
// SERVER SETUP WITH GRACEFUL SHUTDOWN
// ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server...');

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = { app, server };

