#!/usr/bin/env node

// Script to analyze environment variable usage in the codebase

const fs = require('fs');
const path = require('path');

// Patterns to search for environment variable usage
const envPatterns = [
  /process\.env\.(\w+)/g,           // process.env.VAR_NAME
  /process\.env\['([^']+)'\]/g,     // process.env['VAR_NAME']
  /process\.env\["([^"]+)"\]/g,     // process.env["VAR_NAME"]
  /\$\{?(\w+)\}?/g,                 // ${VAR} or $VAR (in shell contexts)
  /(\w+)=["'][^"']*["']/g,          // VAR="value" in .env files
];

// Check for dotenv require/import
const dotenvPatterns = [
  /require\(['"]dotenv['"]\)/,
  /import.*from.*['"]dotenv['"]/,
  /import\s+['"]dotenv\/config['"]/,
];

console.log('=== Environment Variable Analysis ===\n');

// List all files
const files = [];
function walkDir(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!entry.name.startsWith('.') && entry.name !== 'node_modules') {
        walkDir(fullPath);
      }
    } else if (entry.isFile()) {
      files.push(fullPath);
    }
  }
}

walkDir('.');

// Analyze each file
const envVars = new Set();
const dotenvFiles = new Set();
const envFiles = [];
const jsFiles = [];

console.log('Files found:');
for (const file of files) {
  const ext = path.extname(file);
  const filename = path.basename(file);

  if (filename.includes('.env') || filename === '.env') {
    envFiles.push(file);
    console.log(`  📄 ${file} (environment file)`);
  } else if (ext === '.js' || ext === '.ts' || ext === '.jsx' || ext === '.tsx') {
    jsFiles.push(file);
    console.log(`  📜 ${file} (JavaScript/TypeScript)`);
  } else {
    console.log(`  📁 ${file}`);
  }
}

console.log('\n=== Environment Files Analysis ===');
for (const envFile of envFiles) {
  console.log(`\nAnalyzing: ${envFile}`);
  try {
    const content = fs.readFileSync(envFile, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (!line.trim() || line.trim().startsWith('#')) {
        continue;
      }

      // Extract VAR_NAME=value pattern
      const match = line.match(/^(\w+)=/);
      if (match) {
        const varName = match[1];
        envVars.add(varName);
        const value = line.substring(varName.length + 1);

        // Check if it's a canary/test value
        const isCanary = value.includes('CANARY');
        const isSecret = varName.includes('SECRET') || varName.includes('KEY') || varName.includes('PASSWORD');

        console.log(`  🔑 ${varName}: ${isCanary ? '🚨 CANARY/TEST VALUE' : 'production value'} ${isSecret ? '🔒 (secret)' : ''}`);
      }
    }
  } catch (err) {
    console.log(`  ❌ Error reading file: ${err.message}`);
  }
}

console.log('\n=== JavaScript/TypeScript Files Analysis ===');
for (const jsFile of jsFiles) {
  console.log(`\nAnalyzing: ${jsFile}`);
  try {
    const content = fs.readFileSync(jsFile, 'utf8');

    // Check for dotenv usage
    for (const pattern of dotenvPatterns) {
      if (pattern.test(content)) {
        dotenvFiles.add(jsFile);
        console.log(`  📦 Uses dotenv package`);
        break;
      }
    }

    // Find environment variable references
    for (const pattern of envPatterns) {
      const matches = content.matchAll(pattern);
      for (const match of matches) {
        let varName;

        if (pattern === envPatterns[0] || pattern === envPatterns[1] || pattern === envPatterns[2]) {
          varName = match[1];
        } else if (pattern === envPatterns[3]) {
          varName = match[1];
        }

        if (varName && !varName.includes('.')) {
          envVars.add(varName);
          console.log(`  🔍 References: process.env.${varName}`);
        }
      }
    }

    // Check for hardcoded values that should be env vars
    const suspiciousPatterns = [
      { pattern: /port\s*[:=]\s*['"]?\d+['"]?/gi, message: 'Hardcoded port' },
      { pattern: /['"]\d{4,5}['"]/, message: 'Possibly hardcoded port number' },
      { pattern: /https?:\/\/[^'"\s]+/g, message: 'Hardcoded URL' },
      { pattern: /['"][A-Za-z0-9+/]{20,}['"]/g, message: 'Possibly hardcoded secret/base64 value' },
    ];

    for (const { pattern, message } of suspiciousPatterns) {
      const matches = content.match(pattern);
      if (matches) {
        console.log(`  ⚠️  ${message} found: ${matches[0].substring(0, 50)}...`);
      }
    }

  } catch (err) {
