// Enhanced Express application with comprehensive error handling and security features

const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const expressValidator = require('express-validator'); // Input validation
const morgan = require('morgan'); // HTTP request logging
const winston = require('winston'); // Structured logging

const app = express();

// Initialize logger
const logger = winston.createLogger({
    level: 'info',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' })
    ]
});

// Security middleware setup
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"]
        }
    }
}));

// Configure CORS - restrict to trusted origins in production
const corsOptions = {
    origin: process.env.NODE_ENV === 'production' 
        ? process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : []
        : ['http://localhost:3000', 'http://localhost:8080'],
    optionsSuccessStatus: 200,
    credentials: true
};
app.use(cors(corsOptions));

// Rate limiting - prevent brute force and DoS attacks
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again after 15 minutes'
    },
    handler: (req, res, next, options) => {
        logger.warn(`Rate limit exceeded for IP: ${req.ip}`, {
            ip: req.ip,
            path: req.path,
            method: req.method
        });
        res.status(429).json(options.message);
    }
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// Body parsing middleware with size limits
app.use(express.json({
    limit: '10kb', // Prevent large payload attacks
    strict: true // Only accept arrays and objects
}));

app.use(express.urlencoded({
    extended: true,
    limit: '10kb'
}));

// Request logging
app.use(morgan('combined', {
    stream: {
        write: (message) => logger.info(message.trim())
    }
}));

// Simple validation middleware for query parameters
const validateQueryParams = (req, res, next) => {
    // Example: If you add query parameters later, validate them here
    const allowedParams = ['page', 'limit', 'sort', 'filter']; // Example allowed params

    if (Object.keys(req.query).length > 0) {
        const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

        if (invalidParams.length > 0) {
            logger.warn(`Invalid query parameters detected: ${invalidParams.join(', ')}`, {
                ip: req.ip,
                path: req.path,
                invalidParams
            });
            return res.status(400).json({
                error: 'Invalid query parameters',
                invalidParams,
                message: 'Only the following query parameters are allowed: ' + allowedParams.join(', ')
            });
        }
    }
    next();
};

// Global error handling middleware
const errorHandler = (err, req, res, next) => {
    logger.error('Unhandled error:', {
        error: err.message,
        stack: err.stack,
        path: req.path,
        method: req.method,
        ip: req.ip,
        timestamp: new Date().toISOString()
    });

    // Don't expose stack trace in production
    const isProduction = process.env.NODE_ENV === 'production';

    res.status(err.status || 500).json({
        error: isProduction ? 'Internal server error' : err.message,
        details: isProduction ? undefined : err.stack,
        timestamp: new Date().toISOString(),
        requestId: req.id || Math.random().toString(36).substr(2, 9)
    });
};

// Request ID middleware for tracking
app.use((req, res, next) => {
    req.id = Math.random().toString(36).substr(2, 9);
    next();
});

// Health check endpoint with validation
app.get('/health', (req, res, next) => {
    try {
        // Validate no query parameters on health endpoint
        if (Object.keys(req.query).length > 0) {
            logger.warn(`Health endpoint called with query parameters: ${JSON.stringify(req.query)}`);
            return res.status(400).json({
                error: 'No query parameters allowed on health endpoint',
                timestamp: new Date().toISOString()
            });
        }

        // Simulate some health checks
        const healthStatus = {
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
            requestId: req.id
        };

        logger.info('Health check performed', { requestId: req.id });
        res.json(healthStatus);
    } catch (error) {
        next(error); // Pass error to global error handler
    }
});

// Users endpoint with validation
app.get('/users', validateQueryParams, (req, res, next) => {
    try {
        // Validate and sanitize query parameters if any
        const page = parseInt(req.query.page) || 1;
        const limit = parseInt(req.query.limit) || 10;

        if (page < 1) {
            return res.status(400).json({
                error: 'Invalid page parameter',
                message: 'Page must be a positive integer'
            });
        }

        if (limit < 1 || limit > 100) {
            return res.status(400).json({
                error: 'Invalid limit parameter',
                message: 'Limit must be between 1 and 100'
            });
        }

        // Example user data - in a real app, this would come from a database
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        // Sanitize output (remove sensitive data if any)
        const sanitizedUsers = users.map(user => ({
            id: user.id,
            name: user.name,
            email: user.email
        }));

        logger.info('Users list retrieved', { 
            requestId: req.id,
            page,
            limit,
            userCount: sanitizedUsers.length 
        });

        res.json({
            data: sanitizedUsers,
            meta: {
                page,
                limit,
                total: sanitizedUsers.length,
                requestId: req.id
            },
            timestamp: new Date().toISOString()
        });
    } catch (error) {
        next(error); // Pass error to global error handler
    }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
    logger.warn(`404 Not Found: ${req.method} ${req.path}`, {
        ip: req.ip,
        userAgent: req.get('User-Agent'),
        requestId: req.id
    });

    res.status(404).json({
        error: 'Route not found',
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString(),
        requestId: req.id
    });
});

// Register global error handler (must be last)
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
    logger.info('SIGTERM received, starting graceful shutdown');
    server.close(() => {
        logger.info('Server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    logger.info('SIGINT received, starting graceful shutdown');
    server.close(() => {
        logger.info('Server closed');
        process.exit(0);
    });
});

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled promise rejection:', { reason, promise });
    // In production, you might want to exit the process
    if (process.env.NODE_ENV === 'production') {
        process.exit(1);
    }
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
    logger.error('Uncaught exception:', error);
    // In production, you might want to exit the process
    if (process.env.NODE_ENV === 'production') {
        process.exit(1);
    }
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`, {
        port: PORT,
        nodeEnv: process.env.NODE_ENV || 'development',
        pid: process.pid
    });
});

module.exports = { app, server, logger };

// Simple but improved Express application with better security practices

const express = require('express');
const app = express();

// Security best practices ////////////////////////////////////////////
// 1. Set security headers directly (simplified version without helmet)
app.use((req, res, next) => {
    // Prevent clickjacking
    res.setHeader('X-Frame-Options', 'DENY');

    // Prevent MIME type sniffing
    res.setHeader('X-Content-Type-Options', 'nosniff');

    // Enable HSTS in production (requires HTTPS)
    if (process.env.NODE_ENV === 'production') {
        res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    }

    // Basic CSP (Content Security Policy)
    res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: https:");

    // Prevent information disclosure
    res.setHeader('X-Powered-By', 'Express');

    next();
});

// 2. Limit request body size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. Rate limiting middleware (basic implementation)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // 100 requests per window

app.use((req, res, next) => {
    const clientIp = req.ip || req.connection.remoteAddress;
    const now = Date.now();

    if (!requestCounts.has(clientIp)) {
        requestCounts.set(clientIp, []);
    }

    // Clean old requests
    const clientRequests = requestCounts.get(clientIp).filter(time => now - time < RATE_LIMIT_WINDOW);
    requestCounts.set(clientIp, clientRequests);

    // Check rate limit
    if (clientRequests.length >= RATE_LIMIT_MAX) {
        console.warn(`Rate limit exceeded for IP: ${clientIp}`);
        return res.status(429).json({
            error: 'Too many requests',
            message: 'Please try again in 15 minutes'
        });
    }

    // Add current request
    clientRequests.push(now);
    next();
});

// Input Validation Middleware ////////////////////////////////////////
const validateHealthEndpoint = (req, res, next) => {
    // Reject any query parameters on health endpoint
    if (Object.keys(req.query).length > 0) {
        console.warn(`Health endpoint called with query parameters: ${JSON.stringify(req.query)}`);
        return res.status(400).json({
            error: 'Invalid request',
            message: 'Health endpoint does not accept query parameters'
        });
    }
    next();
};

const validateUsersEndpoint = (req, res, next) => {
