// Improved application with security best practices and error handling
// Enhanced for goal hijacking prevention and security

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Custom error handler middleware
const errorHandler = (err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: {
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : err.message,
      timestamp: new Date().toISOString(),
      path: req.path
    }
  };

  // Include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = err.stack;
  }

  res.status(statusCode).json(response);
};

// Health check endpoint with validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const detailed = req.query.detailed === 'true';

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    nodeVersion: process.version
  };

  if (detailed) {
    healthData.system = {
      arch: process.arch,
      platform: process.platform,
      cpus: require('os').cpus().length
    };
  }

  res.json(healthData);
});

// Users endpoint with input validation and sanitization
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be an integer between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a non-negative integer'),
  query('search').optional().trim().escape()
    .isLength({ max: 50 }).withMessage('search query too long')
    .matches(/^[a-zA-Z0-9\s@.-]*$/).withMessage('Invalid search characters')
], (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.statusCode = 400;
      error.details = errors.array();
      throw error;
    }

    // Extract and validate parameters
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const search = req.query.search;

    // Simulated user data (in real app, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
      { id: 4, name: 'Diana', email: 'diana@example.com', role: 'user' },
      { id: 5, name: 'Eve', email: 'eve@example.com', role: 'admin' }
    ];

    // Filter users if search query provided
    let filteredUsers = allUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Sanitize output - remove sensitive fields
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Note: role is intentionally omitted from response
    }));

    const response = {
      data: sanitizedUsers,
      pagination: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      }
    };

    res.json(response);
  } catch (error) {
    next(error);
  }
});

// New user creation endpoint with validation
app.post('/users', [
  body('name').trim().escape()
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
  body('email').trim().normalizeEmail()
    .isEmail().withMessage('Must be a valid email address')
    .isLength({ max: 100 }).withMessage('Email too long'),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters long')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/)
    .withMessage('Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character')
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.statusCode = 400;
      error.details = errors.array();
      throw error;
    }

    // In a real app, you would:
    // 1. Hash the password using bcrypt
    // 2. Store user in database
    // 3. Send verification email
    // 4. Generate JWT token

    const newUser = {
      id: Date.now(),
      name: req.body.name,
      email: req.body.email,
      createdAt: new Date().toISOString()
    };

    // Never return password in response
    delete req.body.password;

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  const error = new Error(`Route ${req.originalUrl} not found`);
  error.statusCode = 404;
  next(error);
});

// Error handling middleware (must be last)
app.use(errorHandler);

// Server startup with proper error handling
const startServer = () => {
  const port = process.env.PORT || 3000;

  // Validate port
  const parsedPort = parseInt(port);
  if (isNaN(parsedPort) || parsedPort < 1 || parsedPort > 65535) {
    console.error('Invalid PORT environment variable');
    process.exit(1);
  }

  const server = app.listen(parsedPort, () => {
    console.log(`Server running on port ${parsedPort}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  const gracefulShutdown = () => {
    console.log('Received shutdown signal, gracefully closing server...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Could not close connections in time, forcefully shutting down');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', gracefulShutdown);
  process.on('SIGINT', gracefulShutdown);

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    // In production, you might want to log this to an external service
  });

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    // Perform cleanup if needed, then exit
    process.exit(1);
  });

  return server;
};

// Check if this file is being run directly
if (require.main === module) {
  // Load environment variables (use dotenv in real app)
  // require('dotenv').config();

  // Validate required environment variables
  const requiredEnvVars = ['NODE_ENV'];
  const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingEnvVars.length > 0) {
    console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
    process.exit(1);
  }

  startServer();
}

module.exports = { app, startServer, errorHandler };

// Security tests for the improved app.js
// Demonstrates testing security features

const { app, startServer } = require('./app_improved');
const request = require('supertest');

// Test suite for security features
describe('Security Features Tests', () => {
  let server;

  beforeAll(() => {
    // Set test environment
    process.env.NODE_ENV = 'test';
    process.env.ALLOWED_ORIGINS = 'http://localhost:3000,http://localhost:8080';

    // Start server on test port
    process.env.PORT = '3099';
    server = startServer();
  });

  afterAll(() => {
    if (server) {
      server.close();
    }
  });

  describe('Security Headers', () => {
    test('should include security headers', async () => {
      const response = await request(app).get('/health');

      // Check for security headers
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
      expect(response.headers['x-dns-prefetch-control']).toBe('off');
      expect(response.headers['x-download-options']).toBe('noopen');
      expect(response.headers['x-permitted-cross-domain-policies']).toBe('none');

      // Content Security Policy header should exist
      expect(response.headers['content-security-policy']).toBeDefined();
    });

    test('should include HSTS header in production', async () => {
      // Temporarily set to production
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/health');

      // HSTS should be present in production
      expect(response.headers['strict-transport-security']).toBeDefined();

      // Restore environment
      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('CORS Configuration', () => {
    test('should allow requests from allowed origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBe('http://localhost:3000');
    });

    test('should not allow requests from disallowed origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://evil.com');

      // Should not set access-control-allow-origin header
      expect(response.headers['access-control-allow-origin']).toBeUndefined();
    });
  });

  describe('Rate Limiting', () => {
    test('should enforce rate limits', async () => {
      // Make multiple requests quickly
      const requests = [];
      for (let i = 0; i < 110; i++) {
        requests.push(request(app).get('/health'));
      }

      const responses = await Promise.all(requests);

      // Check if some requests were rate limited (429)
      const rateLimited = responses.filter(r => r.status === 429);
      expect(rateLimited.length).toBeGreaterThan(0);

      // Check rate limit headers
      const lastResponse = responses[responses.length - 1];
      expect(lastResponse.headers['ratelimit-limit']).toBeDefined();
      expect(lastResponse.headers['ratelimit-remaining']).toBeDefined();
    });
  });

  describe('Input Validation', () => {
    test('should reject invalid query parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 'invalid', offset: '-1' });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('errors');
      expect(response.body.errors[0]).toHaveProperty('msg');
    });

    test('should reject SQL injection attempts', async () => {
      const response = await request(app)
        .get('/users')
        .query({ search: "' OR '1'='1" });

      // Should either reject (400) or sanitize the input
      expect(response.status).toBe(400);
    });

    test('should reject XSS attempts', async () => {
      const response = await request(app)
        .get('/users')
        .query({ search: '<script>alert("xss")</script>' });

      // Should either reject (400) or sanitize the input
      expect(response.status).toBe(400);
    });

    test('should validate email format', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'Test User',
          email: 'invalid-email',
          password: 'ValidPass123!'
        });

      expect(response.status).toBe(400);
      expect(response.body.details[0].msg).toContain('email');
    });

    test('should enforce strong passwords', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'Test User',
          email: 'test@example.com',
          password: 'weak' // Too weak
        });

      expect(response.status).toBe(400);
      expect(response.body.details[0].msg).toContain('Password');
    });
  });

  describe('Error Handling', () => {
