// Improved Express.js Application with Security Best Practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

// Initialize Express app
const app = express();

// Security Middleware Configuration

// 1. Helmet.js for security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'", "'unsafe-inline'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"],
        },
    },
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));

// 2. CORS Configuration
const corsOptions = {
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    credentials: true,
    maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again later.'
    },
    standardHeaders: true,
    legacyHeaders: false,
});
app.use('/api/', apiLimiter);

// 4. Request parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Compression (for production)
app.use(compression());

// 6. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 7. Global Error Handler
app.use((err, req, res, next) => {
    console.error(`Error: ${err.message}`);
    console.error(err.stack);

    // Determine error type and respond appropriately
    if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
        return res.status(400).json({ 
            error: 'Invalid JSON payload' 
        });
    }

    // Generic error response (don't leak stack trace in production)
    const errorResponse = {
        error: process.env.NODE_ENV === 'production' 
            ? 'An unexpected error occurred' 
            : err.message
    };

    res.status(err.status || 500).json(errorResponse);
});

// Health endpoint with validation
app.get('/health', (req, res) => {
    try {
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
            environment: process.env.NODE_ENV || 'development'
        });
    } catch (error) {
        next(error);
    }
});

// Users endpoint with input validation
app.get('/users', 
    // Input validation middleware
    [
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    ],
    (req, res, next) => {
        try {
            // Validate input
            const errors = validationResult(req);
            if (!errors.isEmpty()) {
                return res.status(400).json({ 
                    errors: errors.array(),
                    message: 'Validation failed'
                });
            }

            // Extract and sanitize parameters
            const page = parseInt(req.query.page) || 1;
            const limit = Math.min(parseInt(req.query.limit) || 10, 100);

            // Mock user data (in real app, this would come from a database)
            const users = [
                { 
                    id: 1, 
                    name: 'Alice', 
                    email: 'alice@example.com',
                    safeEmail: 'alice@example.com'.replace(/\./g, '[dot]') // Simple sanitization example
                },
                { 
                    id: 2, 
                    name: 'Bob', 
                    email: 'bob@example.com',
                    safeEmail: 'bob@example.com'.replace(/\./g, '[dot]')
                },
            ];

            // Pagination example
            const startIndex = (page - 1) * limit;
            const endIndex = page * limit;
            const paginatedUsers = users.slice(startIndex, endIndex);

            res.json({
                users: paginatedUsers,
                pagination: {
                    currentPage: page,
                    pageSize: limit,
                    totalPages: Math.ceil(users.length / limit),
                    totalItems: users.length
                }
            });
        } catch (error) {
            next(error);
        }
    }
);

// 404 Handler
app.use((req, res) => {
    res.status(404).json({ 
        error: 'Resource not found',
        path: req.path,
        method: req.method
    });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

// Configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Start server
const server = app.listen(PORT, HOST, () => {
    console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode`);
    console.log(`Listening on http://${HOST}:${PORT}`);
    console.log(`Health check: http://${HOST}:${PORT}/health`);
});

module.exports = { app, server };

// Security Test Examples for Express.js Applications

// Test 1: Input Validation Tests
const validationTests = [
    {
        description: "Valid page parameter",
        input: { page: "1", limit: "10" },
        expected: { isValid: true, page: 1, limit: 10 }
    },
    {
        description: "Invalid page parameter (negative)",
        input: { page: "-1", limit: "10" },
        expected: { isValid: false, error: "Page must be a positive integer" }
    },
    {
        description: "Invalid limit parameter (too large)",
        input: { page: "1", limit: "1000" },
        expected: { isValid: false, error: "Limit must be between 1 and 100" }
    },
    {
        description: "SQL injection attempt",
        input: { page: "1; DROP TABLE users;--", limit: "10" },
        expected: { isValid: false, error: "Page must be a positive integer" }
    },
    {
        description: "XSS injection attempt",
        input: { page: "<script>alert('xss')</script>", limit: "10" },
        expected: { isValid: false, error: "Page must be a positive integer" }
    }
];

// Test 2: Rate Limiting Scenarios
const rateLimitTests = [
    {
        description: "Normal request rate",
        requestsPerMinute: 10,
        expected: "Should succeed"
    },
    {
        description: "High request rate (potential DoS)",
        requestsPerMinute: 150,
        expected: "Should be rate limited after 100 requests"
    }
];

// Test 3: Security Header Tests
const securityHeaderTests = [
    {
        header: "Content-Security-Policy",
        expected: "Present and properly configured"
    },
    {
        header: "X-Frame-Options",
        expected: "DENY or SAMEORIGIN"
    },
    {
        header: "X-Content-Type-Options",
        expected: "nosniff"
    },
    {
        header: "X-XSS-Protection",
        expected: "1; mode=block"
    },
    {
        header: "Strict-Transport-Security",
        expected: "Present in production"
    }
];

// Test 4: Error Handling Tests
const errorTests = [
    {
        description: "Malformed JSON request",
        payload: "{invalid json",
        expected: "400 Bad Request with clear error"
    },
    {
        description: "Large request body (>10kb)",
        payload: "A".repeat(15000),
        expected: "413 Payload Too Large or request rejected"
    },
    {
        description: "Non-existent endpoint",
        endpoint: "/nonexistent",
        expected: "404 Not Found with proper error format"
    }
];

// Test 5: CORS Tests
const corsTests = [
    {
        description: "Request from allowed origin",
        origin: "http://localhost:3000",
        expected: "CORS headers present"
    },
    {
        description: "Request from disallowed origin",
        origin: "http://evil.com",
        expected: "CORS headers missing or error"
    }
];

// Helper function to run security tests
function runSecurityTests() {
    console.log("Security Test Summary");
    console.log("====================\n");

    console.log("1. Input Validation Tests:");
    validationTests.forEach(test => {
        console.log(`   ✓ ${test.description}`);
        // In real app, this would make actual HTTP requests
    });

    console.log("\n2. Rate Limiting Tests:");
    rateLimitTests.forEach(test => {
        console.log(`   ✓ ${test.description}: ${test.expected}`);
    });

    console.log("\n3. Security Header Tests:");
    securityHeaderTests.forEach(test => {
        console.log(`   ✓ ${test.header}: ${test.expected}`);
    });

    console.log("\n4. Error Handling Tests:");
    errorTests.forEach(test => {
        console.log(`   ✓ ${test.description}: ${test.expected}`);
    });

    console.log("\n5. CORS Tests:");
    corsTests.forEach(test => {
        console.log(`   ✓ ${test.description}: ${test.expected}`);
    });

    console.log("\n✅ All security tests would be implemented in a real test suite");
}

// Export for use in test runners
module.exports = {
    validationTests,
    rateLimitTests,
    securityHeaderTests,
    errorTests,
    corsTests,
    runSecurityTests
};

// Run tests if this file is executed directly
if (require.main === module) {
    runSecurityTests();
}

